const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict'),pw=require('playwright');
const engine=process.argv[2]||'chromium',root=process.cwd(),out=path.resolve('qa-education-'+engine,'review-20261030');let browser,server;const errors=[];
(async()=>{
 fs.mkdirSync(out,{recursive:true});server=http.createServer((req,res)=>{let f=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname);if(fs.existsSync(f)&&fs.statSync(f).isDirectory())f=path.join(f,'index.html');if(!f.startsWith(root+path.sep)||!fs.existsSync(f)||!fs.statSync(f).isFile())return res.writeHead(404).end();res.setHeader('Content-Type',({'.js':'application/javascript','.html':'text/html','.css':'text/css'})[path.extname(f)]||'application/octet-stream');res.end(fs.readFileSync(f));});
 await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port;
 browser=await pw[engine].launch(process.env.STUDENTS_BROWSER_EXECUTABLE?{executablePath:process.env.STUDENTS_BROWSER_EXECUTABLE}:{});const context=await browser.newContext({viewport:{width:1440,height:1000},serviceWorkers:'block',acceptDownloads:true});await context.route('**/*',r=>new URL(r.request().url()).origin===base?r.continue():r.abort());
 const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));let plots=0;
 for(const width of [1440,390,320]){await page.setViewportSize({width,height:1000});
  for(const model of ['beam','transient','cycle','pump-suction','refrigeration','lift-origins']){
   await page.goto(base+'/students/model-lab.html?case='+width+'-'+model+'#'+model);await page.waitForFunction(value=>document.getElementById('module')?.value===value,model);await page.locator('#model-results .metric').first().waitFor();assert.equal(await page.locator('#model-error').isVisible(),false,model+' valid defaults');
   const inputs=page.locator('details.teaching-inputs');assert.equal(await inputs.count(),1);if(width<=800){assert.equal(await inputs.getAttribute('open'),null);await inputs.locator(':scope > summary').click();}
   for(const value of await page.locator('#plot-selector option').evaluateAll(nodes=>nodes.map(n=>n.value))){try{await page.locator('#plot-selector').selectOption(value);}catch(error){throw Error(model+'/'+width+'/'+value+' options='+await page.locator('#plot-selector').innerHTML()+': '+error.message);}assert.ok(await page.locator('#model-chart').isVisible());assert.ok(await page.locator('#model-chart').evaluate(n=>n.querySelectorAll('path,polyline,line,rect').length>0));plots++;}
   await page.locator('summary').filter({hasText:'Numerical data and units'}).click();assert.ok(await page.locator('#model-data table').count()>0);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),model+' page reflow '+width);
   assert.ok(await page.locator('#experiment input:visible,#experiment select:visible').evaluateAll(nodes=>nodes.length>0&&nodes.every(n=>{const r=n.getBoundingClientRect();return r.width>0&&r.left>=-1&&r.right<=innerWidth+1})),model+' inputs fit '+width);
   assert.equal(await page.locator('#beam-sketch').isVisible(),model==='beam','Only the beam study shows its support sketch');
   assert.equal(await page.locator('.diagram-tools:visible').count(),model==='beam'?2:1,'Hidden diagrams hide their exploration controls');
   if(width===390){await page.locator('#model-chart').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(out,model+'-390.png')});}
  }
 }
 await page.goto(base+'/students/model-lab.html#beam');await page.waitForFunction(()=>document.getElementById('module')?.value==='beam');await page.locator('details.teaching-inputs > summary').click();const length=page.locator('[name=length]');await length.focus();const before=await length.inputValue();await length.press('ArrowUp');assert.notEqual(await length.inputValue(),before);await length.press('Enter');assert.equal(await page.locator('#model-error').isVisible(),false);
 await page.locator('summary').filter({hasText:'Keep this experiment'}).click();const [saved]=await Promise.all([page.waitForEvent('download'),page.locator('[data-model-save=json]').click()]),jsonPath=path.join(out,'beam.json');await saved.saveAs(jsonPath);const scenario=JSON.parse(fs.readFileSync(jsonPath));assert.ok(scenario.inputs);await length.fill('2');await page.locator('#model-scenario').setInputFiles(jsonPath);await page.waitForFunction(()=>document.getElementById('model-feedback').textContent.includes('restored'));assert.equal(Number(await length.inputValue()),scenario.inputs.length,await page.locator('#model-feedback').textContent());
 const autosave=page.locator('.study-session input[type=checkbox]');await autosave.check();await length.fill('8');await page.waitForFunction(()=>{const text=localStorage.getItem('mt.study.draft.v1:engineering:beam');return text&&JSON.parse(text).data.some(f=>f.key.includes(':length:')&&f.value==='8')});await page.reload();assert.equal(await length.inputValue(),'8');await page.locator('details.teaching-inputs > summary').click();await autosave.uncheck();
 await length.fill('0');assert.ok(await page.locator('#model-error').isVisible());assert.equal(await page.locator('#model-results .metric').count(),0);assert.ok(await page.locator('[data-model-save=json]').isDisabled());assert.equal(await page.locator('#model-chart').isVisible(),false);assert.equal(await page.locator('.diagram-tools:visible').count(),0);
 await page.goto(base+'/students/index.html#practice-chapter-5');await page.locator('#exercise-question').waitFor();await page.locator('#practice-difficulty').selectOption('Intermediate');await page.locator('#exercise-next').click();assert.equal(await page.locator('#exercise-question').getAttribute('data-exercise-id'),'practice-c05-q10');await page.locator('#exercise-answer').fill('1e-10');await page.locator('#exercise-answer').press('Enter');assert.equal(await page.locator('#exercise-feedback').getAttribute('class'),'correct');await page.locator('#show-solution').click();assert.ok(await page.locator('#exercise-solution').isVisible());
 await page.locator('#practice-chapter').selectOption('1');await page.locator('#practice-subject').selectOption('electrical');assert.equal(await page.locator('#exercise-index').textContent(),'0 / 0');assert.ok(await page.locator('#exercise-answer').isDisabled());assert.equal(await page.locator('#exercise-solution').textContent(),'');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
 await page.goto(base+'/students/interactive.html#beam');const select=page.locator('#module-quick');assert.equal(await select.locator('option').count(),45);const frame=page.frameLocator('#frames iframe');await frame.locator('#model-results .metric').first().waitFor();assert.equal(await frame.locator('body').evaluate(n=>n.scrollWidth<=innerWidth+1),true);
 await frame.locator('#model-chapter a').last().click();await page.waitForURL('**/students/#practice-chapter-3');assert.equal(await page.locator('#practice-chapter').inputValue(),'3');
 assert.deepEqual(errors,[]);console.log(JSON.stringify({status:'PASS',engine,widths:[1440,390,320],newModels:6,plotViewsChecked:plots,modules:32,scope:'Real rendering/reflow, numerical tables, keyboard, scenario download/restore, invalid-state clearing, practice answers/filters and embedded model-to-chapter navigation.',errors}));
})().catch(e=>{console.error(e);process.exitCode=1}).finally(async()=>{await browser?.close();server?.close()});
